/* Tour Pokémon : tombes, bouquets et spectres non identifiés découpés dans des captures de Pokémon Let's Go Pikachu / Évoli envoyées par Raphaël (voir CREDITS.md) */
const TW = { img:null, R:{"tomb":[0,0,99,128],"tombG":[101,0,99,128],"slab":[202,0,7,128],"slabG":[211,0,7,128],"fl0":[220,0,35,32],"fl1":[257,0,37,32],"vase":[296,0,64,63],"pink_body":[362,0,106,119,0.0,0.0],"pink_hand":[470,0,52,31,109.3,47.3],"blue_body":[524,0,89,107,0.0,0.0],"blue_hand":[615,0,59,38,97.3,47.7]}, G:{"pink":{"w":161.33333333333334,"h":118.66666666666667},"blue":{"w":156.0,"h":107.33333333333333}} };
(() => { const im = new Image(); im.onload = () => { TW.img = im; TW.floor = null; for (const c of chunkData.values()) c.canvas = null; }; im.src = "data:image/png;base64,"; })();
const pokeTowerOn = () => LEVEL.tower && !LEVEL.sprout && TW.img;
const TW_K = .55, TW_U = 74; // échelle des tombes (unités du monde par pixel de l'atlas), pas de la grille des tombes
function twSpr(g, n, x, y, k = TW_K, flip = false) { const r = TW.R[n]; if (!flip) return g.drawImage(TW.img, r[0], r[1], r[2], r[3], x, y, r[2] * k, r[3] * k);
  g.save(); g.translate(x + r[2] * k, y); g.scale(-1, 1); g.drawImage(TW.img, r[0], r[1], r[2], r[3], 0, 0, r[2] * k, r[3] * k); g.restore(); }
// les tombes de la grille deviennent des rangées alignées, reliées par leur dalle (pas de piliers ni de bougies)
function pokeTowerRows(x0, y0, graves, pillars, candles) {
  pillars.length = 0; candles.length = 0;
  graves.sort((a, b) => a.gj - b.gj || a.gi - b.gi);
  for (let i = 0, run = 0; i < graves.length; i++) {
    const g = graves[i], p = graves[i - 1];
    run = p && p.gj === g.gj && p.gi === g.gi - 1 ? run + 1 : 1;
    if (run > 4) { graves.splice(i--, 1); run = 0; continue; } // pas de rangée de plus de 4 tombes
    g.x = x0 + g.gi * TW_U + 37; g.y = y0 + g.gj * 92 + 46; g.row = true;
    g.grey = hash(g.x * .37, g.y * .91) < .25;
  }
  for (let i = 0; i < graves.length; i++) { const g = graves[i], n = graves[i + 1]; g.next = !!(n && n.gj === g.gj && n.gi === g.gi + 1); }
}
function pokeTowerFogs(x0, y0, graves) { // nappes de brume posées au pied des tombes (tirage à part, la disposition ne bouge pas)
  const fogs = [], n = 2 + Math.floor(hash(x0 * .013 + 4, y0 * .017 - 9) * 3);
  for (let k = 0; k < n; k++) {
    const h1 = hash(x0 + k * 97, y0 - k * 53), h2 = hash(x0 - k * 31, y0 + k * 71), gr = graves.length && h1 < .75 ? graves[Math.floor(h2 * graves.length)] : null;
    fogs.push({ x:gr ? gr.x + (h2 - .5) * 60 : x0 + h1 * CH, y:gr ? gr.y + 10 : y0 + h2 * CH, s:.8 + h1 * .6, ph:h2 * 6.28, n:4 + Math.floor(h1 * 3) });
  }
  return fogs;
}
const TW_PAL = [[150,184,150],[138,172,140],[124,160,128],[158,186,166],[196,200,198],[178,186,180],[96,118,104],[120,126,128]];
function twFloorTile(i, j) { // couleur d'une dalle (motif continu d'un morceau de carte à l'autre) : verts, blancs et gris, sans violet (le violet vient de la brume)
  const h = hash(i * 1.7 + 11, j * 2.3 - 5), n = fbm(i / 7 + 30, j / 7 - 20);
  if (n > .62) return TW_PAL[h < .6 ? 4 : 5];                         // plaques claires
  if (h < .05) return TW_PAL[6]; if (h < .09) return TW_PAL[7]; if (h < .14) return TW_PAL[4];
  return TW_PAL[h < .55 ? 0 : h < .8 ? 3 : h < .92 ? 1 : 2];
}
function renderPokeTowerChunk(ci, cj) {
  const c = getChunk(ci, cj), x0 = ci * CH, y0 = cj * CH, T = 32;
  const cv2 = document.createElement("canvas"); cv2.width = cv2.height = CH * CH_SCALE;
  const g = cv2.getContext("2d"); g.scale(CH_SCALE, CH_SCALE); g.translate(-x0, -y0); g.imageSmoothingEnabled = true;
  for (let ty = y0; ty < y0 + CH; ty += T) for (let tx = x0; tx < x0 + CH; tx += T) { // carrelage vert et lilas, allée claire
    const i = tx / T, j = ty / T, onPath = Math.abs(ty + T / 2 - pathY(tx + T / 2)) < 40;
    const col = onPath ? (hash(i, j) < .5 ? [200,200,208] : [184,186,196]) : twFloorTile(i, j), v = (hash(i + .5, j - .5) - .5) * 8;
    g.fillStyle = `rgb(${col[0] + v},${col[1] + v},${col[2] + v})`; g.fillRect(tx, ty, T, T);
    { const sh = g.createLinearGradient(tx, ty, tx + T, ty + T); sh.addColorStop(0, "rgba(255,255,255,.14)"); sh.addColorStop(1, "rgba(40,30,70,.10)"); g.fillStyle = sh; g.fillRect(tx + 1, ty + 1, T - 2, T - 2); }
        g.fillStyle = "rgba(236,234,246,.55)"; g.fillRect(tx, ty, T, 1); g.fillRect(tx, ty, 1, T);
  }
  const all = [];
  for (let a = -1; a <= 1; a++) for (let b2 = -1; b2 <= 1; b2++) all.push(...(getChunk(ci + a, cj + b2).graves || []));
  all.sort((a, b) => a.y - b.y);
  const r = TW.R.tomb, W = r[2] * TW_K, H = r[3] * TW_K;
  for (const gr of all) { // tombe, puis la dalle qui la relie à la suivante
    const x = gr.x, yb = gr.y + 14;
    ell(g, x + (gr.next ? TW_U / 2 : 0), yb - 2, gr.next ? TW_U / 2 + W / 2 : W / 2 + 4, 7, "rgba(30,10,50,.28)");
    if (gr.next) { const s = TW.R[gr.grey ? "slabG" : "slab"]; g.drawImage(TW.img, s[0], s[1], s[2], s[3], x + W / 2 - 3, yb - H, TW_U - W + 6, H); }
    twSpr(g, gr.grey ? "tombG" : "tomb", x - W / 2, yb - H, TW_K);
    if (gr.fl) { const k = hash(gr.x + 1, gr.y) < .5 ? "fl0" : "fl1", f = TW.R[k]; for (const s of [-1, 1]) twSpr(g, k, x + s * 13 - f[2] * TW_K * .5, yb - H * .47, TW_K * .85); }
  }
  c.canvas = cv2; return cv2;
}
// spectre non identifié (sans Scope Sylphe), d'après Let's Go : corps et main qui flotte à part
function drawVeiledGhost(c, f, x, y, t, fade) {
  const pink = hash(f.ph * 13.1, 2.7) < .5, n = pink ? "pink" : "blue", G = TW.G[n], b = TW.R[n + "_body"], h = TW.R[n + "_hand"];
  const k = f.r * 3.3 / G.h, w = G.w * k, x0 = -w / 2, y0 = -G.h * k / 2, bob = Math.sin(t * 4 + f.ph) * 3;
  c.save(); c.translate(x, y); if (f.flip) c.scale(-1, 1); c.globalAlpha = fade * .95;
  ell(c, 0, G.h * k * .55, w * .3, 5, "rgba(20,0,40,.3)");
  c.drawImage(TW.img, b[0], b[1], b[2], b[3], x0, y0, b[2] * k, b[3] * k);
  c.drawImage(TW.img, h[0], h[1], h[2], h[3], x0 + h[4] * k, y0 + h[5] * k + bob, h[2] * k, h[3] * k);
  c.restore();
}
// brume violette de Let's Go : nappes au ras du sol, faites de bouffées qui ondulent et dérivent doucement
let TW_PUFF = null;
function twPuff() {
  if (TW_PUFF) return TW_PUFF;
  const c = document.createElement("canvas"); c.width = 128; c.height = 128; const g = c.getContext("2d");
  const gr = g.createRadialGradient(64, 64, 0, 64, 64, 64);
  gr.addColorStop(0, "rgba(186,120,245,.55)"); gr.addColorStop(.45, "rgba(160,90,230,.42)"); gr.addColorStop(.75, "rgba(140,70,215,.18)"); gr.addColorStop(1, "rgba(130,60,205,0)");
  g.fillStyle = gr; g.fillRect(0, 0, 128, 128); return TW_PUFF = c;
}
function drawTowerFog(camX, camY, vw, vh, t) {
  const P = twPuff();
  forView(camX, camY, vw, vh, 260, (i, j, c) => { for (const f of c.fogs || []) {
    const dx = Math.sin(t * .12 + f.ph) * 36, dy = Math.cos(t * .09 + f.ph) * 10;
    for (let k = 0; k < f.n; k++) {
      const a = f.ph + k * 2.4 + t * .18, rr = (34 + k * 9) * f.s, R = (62 + 18 * Math.sin(t * .5 + k + f.ph)) * f.s;
      const x = f.x + dx + Math.cos(a) * rr, y = f.y + dy + Math.sin(a) * rr * .45;
      cx.globalAlpha = .45 + .18 * Math.sin(t * .7 + k * 1.3 + f.ph);
      cx.drawImage(P, x - R * 1.3, y - R * .75, R * 2.6, R * 1.5);
    }
  } });
  cx.globalAlpha = 1;
}
